<?php
namespace App\Http\Controllers;
use App\Models\Product; use Illuminate\Http\Request; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class ProductController extends Controller {public function index():View{return view('products.index',['products'=>Product::latest()->paginate(12)]);} public function create():View{return view('products.form');}public function store(Request $r):RedirectResponse{$p=Product::create($r->validate(['sku'=>'required|string|max:60|unique:products,sku','name'=>'required|string|max:180','category'=>'nullable|string|max:100','quantity'=>'required|integer|min:0','reorder_level'=>'required|integer|min:0','unit_price'=>'required|numeric|min:0']));return redirect()->route('products.index')->with('success','Product added.');}public function edit(Product $product):View{return view('products.form',compact('product'));}public function update(Request $r,Product $product):RedirectResponse{$product->update($r->validate(['sku'=>'sometimes|required|string|max:60|unique:products,sku,'.$product->id,'name'=>'sometimes|required|string|max:180','category'=>'nullable|string|max:100','quantity'=>'sometimes|required|integer|min:0','reorder_level'=>'sometimes|required|integer|min:0','unit_price'=>'sometimes|required|numeric|min:0']));return redirect()->route('products.index')->with('success','Product updated.');}public function destroy(Product $product):RedirectResponse{$product->delete();return redirect()->route('products.index')->with('success','Product deleted.');}}
